// ai-agents/harness/src/telemetry.ts  (the harness itself is G3's)
import { readFileSync } from "node:fs";
// harness/package.json is one level above both src/ and dist/; its version changes on every harness release
const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")) as { version: string };
export const HARNESS_VERSION = pkg.version;
export const STEPS = ["ticket", "plan", "plan_ok", "vm", "build", "pr", "byte", "approve", "learn"] as const;
export type Step = (typeof STEPS)[number];
export interface RunTags { agent: string; jira: string; id: string }
/** Env for one Agent SDK session. Its OTel data and its gateway calls carry the same tags. */
export function stepEnv(run: RunTags, step: Step): Record<string, string> {
  if (!STEPS.includes(step)) throw new Error(`unknown step ${step}`);
  const tags = { agent: run.agent, jira: run.jira, run: run.id, step, "harness.version": HARNESS_VERSION };
  return {
    OTEL_RESOURCE_ATTRIBUTES: Object.entries(tags).map(([k, v]) => `${k}=${v}`).join(","),
    // agent, jira and run reach the gateway inside the run token; step and version ride on headers
    ANTHROPIC_CUSTOM_HEADERS: `x-ai-agents-step: ${step}\nx-ai-agents-harness: ${HARNESS_VERSION}`,
  };
}
// In a step (no maxTurns, no maxBudgetUsd, no taskBudget: the far-away backstop acts between turns, in the harness).
// options.env replaces the session's whole environment, so spread process.env (gateway URL and run token) first:
//   const options: Options = { model: route.model, effort: route.effort, env: { ...process.env, ...stepEnv(run, "build") } };
//   for await (const message of query({ prompt: task, options })) { ... }
// The Temporal workflow also sets search attributes Step and HarnessVersion for the same run
// (upsertSearchAttributes with typed keys from defineSearchAttributeKey).

// ai-agents/harness/src/label-run.ts  (npx tsx harness/src/label-run.ts <run-id> --failed-at ... --cause ...)
// Weekly run review: label a failed run with where it failed and which step should have caught it.
import { parseArgs } from "node:util";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { STEPS } from "./telemetry.js";

const CAUSES = ["too_many_tools", "bad_handoff", "contradicting_prompt", "missing_context",
  "flaky_environment", "model", "unknown"] as const;

const { values: a, positionals: [runId] } = parseArgs({
  allowPositionals: true,
  options: {
    "failed-at": { type: "string" },
    "should-have-caught": { type: "string" },
    cause: { type: "string" },
    note: { type: "string", default: "" }, // one line; no PHI, no secrets, no customer names
  },
});

const oneOf = (flag: string, value: string | undefined, allowed: readonly string[]): string => {
  if (!value || !allowed.includes(value)) throw new Error(`--${flag} must be one of: ${allowed.join(", ")}`);
  return value;
};
if (!runId) throw new Error("usage: label-run <run-id> --failed-at <step> --should-have-caught <step> --cause <cause>");

const label = { // the JSON keys are what the nightly job and the dashboards read
  run: runId, failed_at: oneOf("failed-at", a["failed-at"], STEPS),
  should_have_caught: oneOf("should-have-caught", a["should-have-caught"], STEPS),
  cause: oneOf("cause", a.cause, CAUSES), note: a.note, labelled_at: new Date().toISOString(),
};
await new S3Client({}).send(new PutObjectCommand({
  Bucket: "rhino-ai-agents-eval-results", Key: `runs/${runId}/label.json`,
  Body: JSON.stringify(label), ContentType: "application/json",
}));
console.log(`${runId}: failed at ${label.failed_at}, should have been caught at ${label.should_have_caught}`);

// ai-agents/metrics/src/quality.ts
// Step-quality numbers per agent and week, from run records. A gate's number, not a person's.
import type { Approval, ByteFinding, CheckRun, RunRecord } from "./types.js";

/** Tickets that passed the readiness check without being sent back / tickets assigned to Nova. */
export function readyOnFirstTry(runs: RunRecord[]): number | null {
  const assigned = runs.filter((r) => r.agent === "nova");
  return assigned.length ? assigned.filter((r) => r.readiness.sent_back === 0).length / assigned.length : null;
}

export function planAdherence(run: RunRecord, changedFiles: string[]) {
  const planned = new Set(run.plan.files);
  return {
    unplanned_files: new Set(changedFiles.filter((f) => !planned.has(f))).size,
    items_not_done: run.plan.items.filter((item) => !item.done).length,
  };
}

/** The required checks on the PR's first pushed commit were all green. */
export function firstPassGreen(checkRuns: CheckRun[], required: Set<string>): boolean {
  const first = checkRuns.reduce((a, b) => (b.started_at < a.started_at ? b : a)); // ISO strings compare by time
  return checkRuns.filter((c) => c.head_sha === first.head_sha && required.has(c.name)).every((c) => c.conclusion === "success");
}

export function caughtBeforePr(run: RunRecord, byteFindings: ByteFinding[]): number | null {
  const fixed = run.self_review.important_fixed; // from the self-review receipt in the PR
  const left = byteFindings.filter((f) => (f.severity === "HIGH" || f.severity === "MED") && f.new).length;
  return fixed + left ? fixed / (fixed + left) : null;
}

/** Plan or PR approvals given under 60 s after the request: run links for the weekly review. */
export function fastApprovals(approvals: Approval[], seconds = 60): string[] {
  return approvals.filter((a) => Date.parse(a.approved_at) - Date.parse(a.requested_at) < seconds * 1000).map((a) => a.run_url);
}

